package com.trush.game.world;

import com.trush.game.objects.Prop;

/**
 * A story stage (a floor's look and feel): its name, music, room themes (tilesets generated by
 * tools/gen_sprites.py), how layout letters map to furniture, and the door barricade style.
 * Floor 1 is the village, floor 2 the town, floor 3 the city (at night), floor 4 the skyscraper -
 * a straight climb by elevator, floor after floor, up to its roof - and floor 5 the clouds, where
 * the Fluffy King sits on his throne.
 */
public enum Stage {
    VILLAGE("THE VILLAGE", "village", "boss_village", "yard", "chapel", "square",
            new String[]{"cottage", "yard", "barn", "orchard", "square"},
            "The village is safe... for now.", Barricade.PLANKS, 0f, false, Exit.GATE),
    TOWN("THE TOWN", "town", "boss_town", "street", "shop", "townhall",
            new String[]{"street", "market", "alley", "park"},
            "The town is quiet... for now.", Barricade.ROAD, 0.45f, false, Exit.BUS),
    CITY("THE CITY", "city", "boss_city", "avenue", "pawnshop", "helipad",
            new String[]{"avenue", "subway", "rooftop", "construction"},
            "The city sleeps... for now.", Barricade.TAPE, 0.3f, true, Exit.DOORS),
    SKYSCRAPER("THE SKYSCRAPER", "tower", "boss_tower", "lobby", "vault", "roof",
            new String[]{"office", "servers", "cafeteria"},
            "The tower has fallen... for now.", Barricade.SHUTTER, 0f, false, Exit.HELICOPTER),
    CLOUDS("THE FLUFFY KINGDOM", "sky", "boss", "cloudgate", "rainbow", "throne",
            new String[]{"clouds", "temple", "storm"},
            "The skies are clear... for good.", Barricade.CLOUD, 0.4f, false, Exit.RAINBOW);

    /** What's drawn across the doors of a locked room. */
    public enum Barricade { PLANKS, ROAD, TAPE, SHUTTER, CLOUD }

    /**
     * The way on to the next floor that opens after the boss: its sprite in props.txt, the size of the
     * spot you stand on to use it (at the bottom of the sprite), and the prompt.
     */
    public enum Exit {
        HATCH("exit", 1.0f, 0.75f, "GO DOWN"),
        GATE("exit_gate", 0.9f, 0.5f, "ON TO THE TOWN"),
        BUS("exit_bus", 1.1f, 0.5f, "CATCH THE BUS"),
        DOORS("exit_doors", 0.9f, 0.5f, "ENTER THE TOWER"),
        HELICOPTER("exit_heli", 1.6f, 0.6f, "FLY AWAY"),
        RAINBOW("exit_rainbow", 1.2f, 0.5f, "SLIDE HOME");

        public final String sprite;
        public final float w;
        public final float h;
        public final String prompt;

        Exit(String sprite, float w, float h, String prompt) {
            this.sprite = sprite;
            this.w = w;
            this.h = h;
            this.prompt = prompt;
        }
    }

    public final String title;
    /** Track in assets/music/ (without .ogg). */
    public final String music;
    /** Track for this stage's boss fights ("Harvest of Fear", "Rush Hour Rampage"...). */
    public final String bossMusic;
    public final String startTheme;
    public final String treasureTheme;
    public final String bossTheme;
    public final String[] combatThemes;
    /** Line on the floor-clear screen. */
    public final String clearText;
    public final Barricade barricade;
    /** Chance that a combat room has open sewer hatches (pits) in its floor. */
    public final float pitChance;
    /** Night: a darkness vignette around the player, lamps cast light (GameWorld.drawNight). */
    public final boolean night;
    /** How you leave the floor once its boss is beaten. */
    public final Exit exit;

    Stage(String title, String music, String bossMusic, String startTheme, String treasureTheme, String bossTheme,
          String[] combatThemes, String clearText, Barricade barricade, float pitChance, boolean night, Exit exit) {
        this.title = title;
        this.music = music;
        this.bossMusic = bossMusic;
        this.startTheme = startTheme;
        this.treasureTheme = treasureTheme;
        this.bossTheme = bossTheme;
        this.combatThemes = combatThemes;
        this.clearText = clearText;
        this.barricade = barricade;
        this.pitChance = pitChance;
        this.night = night;
        this.exit = exit;
    }

    /** The skyscraper is climbed by elevator: its rooms are stacked floors (StageMap.tower), not a maze. */
    public boolean isTower() {
        return this == SKYSCRAPER;
    }

    /** The clouds: open sky all round the rooms (their edges are see-through), holes to fall through. */
    public boolean isSky() {
        return this == CLOUDS;
    }

    /** The props.txt sprite of a pit: an open sewer hatch, or a hole in the clouds. */
    public String pitSprite() {
        return isSky() ? "pit_sky" : "pit";
    }

    /** The last story floor: beating its boss wins the run (the victory screen). */
    public static int lastFloor() {
        return values().length;
    }

    /** The stage of a story floor (1-based); floors beyond the last stage stay on it. */
    public static Stage forFloor(int floor) {
        Stage[] all = values();
        return all[Math.max(0, Math.min(floor, all.length) - 1)];
    }

    /**
     * Furniture for a layout letter (see RoomTemplates): the town has benches and lamps, the city parked cars
     * and lamps, the clouds cloud banks, marble columns, golden urns and presents.
     */
    public Prop.Kind propFor(char c) {
        if (isSky()) {
            switch (c) {
                case 'H':
                    return Prop.Kind.CLOUD;
                case 'P':
                    return Prop.Kind.COLUMN;
                case 'B':
                    return Prop.Kind.URN;
                case 'C':
                    return Prop.Kind.GIFT;
                default:
                    break;
            }
        }
        switch (c) {
            case 'T':
                return Prop.Kind.TABLE;
            case 'H':
                return this == TOWN ? Prop.Kind.BENCH : this == CITY ? Prop.Kind.CAR
                        : this == SKYSCRAPER ? Prop.Kind.DESK : Prop.Kind.HAY;
            case 'B':
                return this == SKYSCRAPER ? Prop.Kind.COOLER : Prop.Kind.BARREL;
            case 'C':
                return Prop.Kind.CRATE;
            case 'K': // a parked car on any stage (the Traffic Light's arena)
                return Prop.Kind.CAR;
            case 'P':
                return this == VILLAGE ? Prop.Kind.PILLAR : this == SKYSCRAPER ? Prop.Kind.PLANT : Prop.Kind.LAMP;
            default:
                return null;
        }
    }
}
